mapper.select:
SELECT R.CHECKLIST_ID AS CHECKLIST_ID, I.ITEM_NAME AS ITEM_NAME, I.SEVERITY_CD AS SEVERITY_CD, R.TARGET_TYPE AS TARGET_TYPE, R.TARGET_ID AS TARGET_ID, R.REMARK AS REMARK FROM TB_IF_CHECKLIST_RESULT_PILOT R JOIN TB_IF_CHECKLIST_ITEM_PILOT I ON I.CHECKLIST_ID = R.CHECKLIST_ID WHERE R.CHECKED_YN = 'N' AND NVL(I.ACTIVE_YN, 'Y') = 'Y' AND I.SEVERITY_CD = #{severityCd}
AND (UPPER(NVL(R.TARGET_ID,'')) LIKE '%'||UPPER(#{keyword})||'%' OR UPPER(NVL(I.ITEM_NAME,'')) LIKE '%'||UPPER(#{keyword})||'%')
ORDER BY I.SEVERITY_CD, R.TARGET_ID, I.SORT_NO
